import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-leave-dashboard',
  templateUrl: './leave-dashboard.page.html',
  styleUrls: ['./leave-dashboard.page.scss'],
})
export class LeaveDashboardPage implements OnInit {

  constructor(private router: Router) { }

  ngOnInit() {
  }

  navigateBack() {
    this.router.navigate(['/tabs/stem-dashboard']);
  }

  applyAlert() {
    this.router.navigate(['/tabs/stem-leave']);
  }

  approvedAlert() {
    this.router.navigate(['/tabs/leave-history']);
  }

}
